# Read the current run method of TocTreeprocessor
with open('markdown/extensions/toc.py') as f:
    content = f.read()

lines = content.split('\n')
in_run = False
for i, line in enumerate(lines):
    if 'def run(self, doc' in line:
        in_run = True
    if in_run:
        print(f"{i}: {line}")
        if line.strip() == '' and i > 0 and lines[i-1].strip().startswith('self.md.toc ='):
            break
